"""aw start-task: sync main, create branch and worktree."""

from __future__ import annotations

import re
import subprocess
import sys
from datetime import date
from pathlib import Path

from aw import rollup, session, trackers
from aw.config import PROJECT_FILE, STDERR_FD, AwError, Config, fast_forward, git

SLUG = re.compile(r"^[a-z0-9]+(-[a-z0-9]+)*$")

ENVRC = """\
# Delegates to the primary checkout's .envrc (generated by aw start-task).
source_env "$(dirname "$(git rev-parse --path-format=absolute --git-common-dir)")"
"""


def _fill(cfg: Config, key: str, ph: dict[str, str]) -> str:
    """Expand a name template; without an issue, drop {issue} and its separator."""
    template = cfg.values[key]
    if not ph["issue"]:
        for part in ("{issue}-", "-{issue}", "{issue}/", "{issue}"):
            template = template.replace(part, "")
    return cfg.expand(template, **ph)


def _direnv(worktree: Path) -> None:
    """Delegate to the primary checkout's .envrc unless the project tracks its own; trouble with direnv is a warning,
    since the worktree and branch exist already and the rest of the start still runs.

    Only the delegating .envrc aw writes is allowed here. A tracked one runs on the host with the user's environment,
    and whoever changed it last (a merged branch, the --base branch) is not the user: the user reads it and allows it.
    """
    envrc = worktree / ".envrc"
    if envrc.exists():
        print(
            f"warning: {envrc} is tracked, so aw does not allow it: read it, then `direnv allow {worktree}`",
            file=sys.stderr,
        )
        return
    envrc.write_text(ENVRC)
    try:
        r = subprocess.run(["direnv", "allow", str(worktree)], stdout=STDERR_FD, check=False)
    except FileNotFoundError:
        print("warning: direnv allow: direnv not found; install it or set direnv = false", file=sys.stderr)
        return
    if r.returncode:
        print(f"warning: direnv allow exited {r.returncode}; run it in {worktree}", file=sys.stderr)


def run(cfg: Config, kind: str, slug: str, issue: str | None, base: str | None = None) -> dict[str, str]:
    for key in ("branch_name", "worktree_name", "on_start"):
        if "{n}" in cfg.values[key]:
            raise AwError(
                f"{key} uses {{n}}, the session number, which is gone: worktrees are named {{issue}}-{{slug}}, "
                "or {slug} without an issue; remove {n} from it"
            )
    tracker = trackers.get(cfg)
    issue = tracker.normalize(issue) if issue else ""
    types = cfg.get("branch_types")
    if kind not in types:
        raise AwError(f"type {kind!r} not in: {' '.join(types)}")
    if not SLUG.match(slug):
        raise AwError(f"slug must be kebab-case: {slug!r}")

    root, main = cfg.root, cfg.get("main_branch")
    if base and cfg.get("forge") == "none":
        raise AwError("--base needs a forge: aw restack follows the base through its merge request")
    if base == main:
        raise AwError(f"--base {main}: a session already starts from {main}")
    if base and not git("ls-remote", "--heads", "origin", base, cwd=root):
        raise AwError(f"origin has no branch {base}; push it first")
    # The worktree starts from the main ref, so the primary checkout may have any branch checked out.
    if "origin" in git("remote", cwd=root).split():
        fast_forward(root, main)
    else:
        print("warning: no 'origin' remote, skipping pull", file=sys.stderr)

    ph = {"type": kind, "slug": slug, "date": date.today().strftime("%Y%m%d"), "issue": issue}
    branch = _fill(cfg, "branch_name", ph)
    cfg.public(branch)  # the session pushes it
    worktree = Path(cfg.get("worktree_root", **ph)) / _fill(cfg, "worktree_name", ph)

    if (
        subprocess.run(
            ["git", "show-ref", "--verify", "--quiet", f"refs/heads/{branch}"], cwd=root, check=False
        ).returncode
        == 0
    ):
        raise AwError(f"branch exists: {branch}")
    if worktree.exists():
        raise AwError(f"path exists: {worktree}")

    worktree.parent.mkdir(parents=True, exist_ok=True)
    start = main
    if base:
        git("fetch", "--quiet", "origin", base, cwd=root)
        start = git("rev-parse", f"origin/{base}", cwd=root)
    git("worktree", "add", "--quiet", "-b", branch, str(worktree), start, cwd=root)
    if not (worktree / PROJECT_FILE).is_file():
        print(
            f"warning: {PROJECT_FILE} is not committed on {main}, so this worktree has none and aw runs here "
            "with defaults (no tracker, no hooks); commit .agents/ on main",
            file=sys.stderr,
        )
    session.write(
        worktree,
        {
            "issue": issue,
            "type": kind,
            "slug": slug,
            "started": date.today().isoformat(),
            **({"base": base, "fork_point": start} if base else {}),
        },
    )

    if cfg.get("direnv"):
        _direnv(worktree)

    if issue and cfg.get("sync_issue_status"):
        try:
            for message in tracker.advance(issue, "in_progress"):
                print(message, file=sys.stderr)
        except AwError as e:
            print(f"warning: issue status not updated: {e}", file=sys.stderr)
        try:
            for message in rollup.start(tracker, issue):
                print(f"parent: {message}", file=sys.stderr)
        except AwError as e:
            print(f"warning: parent status not updated: {e}", file=sys.stderr)

    if cfg.values["on_start"] and (hook := cfg.command("on_start", **ph)):
        r = subprocess.run(hook, shell=True, cwd=worktree, stdout=STDERR_FD, check=False)  # noqa: S602 - hooks are shell commands the user configured
        if r.returncode:
            print(f"warning: on_start exited {r.returncode}", file=sys.stderr)

    return {"branch": branch, "worktree": str(worktree), "issue": issue}
